`const http = require("http");

const PORT = 11435;
const OLLAMA_HOST = "192.168.0.32";
const OLLAMA_PORT = 11434;

/**
 * Qwen 3.8 requires system messages to appear only at the beginning.
 *
 * OpenCode may send multiple system messages throughout the message array.
 *
 * This function:
 *   1. Collects every system message.
 *   2. Merges their content.
 *   3. Places one system message at position 0.
 *   4. Preserves every non-system message unchanged.
 */
function mergeSystemMessages(messages) {
    if (!Array.isArray(messages)) {
        return messages;
    }

    const systemMessages = [];
    const otherMessages = [];

    for (const message of messages) {
        if (message.role === "system") {
            systemMessages.push(message);
        } else {
            otherMessages.push(message);
        }
    }

    if (systemMessages.length === 0) {
        return messages;
    }

    // Preserve string or structured content.
    const allStrings = systemMessages.every(
        (message) => typeof message.content === "string"
    );

    let content;

    if (allStrings) {
        content = systemMessages
            .map((message) => message.content)
            .filter(Boolean)
            .join("\n\n");
    } else {
        // Handle OpenAI-style structured content arrays.
        content = systemMessages.flatMap((message) => {
            if (Array.isArray(message.content)) {
                return message.content;
            }

            if (typeof message.content === "string") {
                return [
                    {
                        type: "text",
                        text: message.content,
                    },
                ];
            }

            return [];
        });
    }

    console.log(
        `[proxy] merged ${systemMessages.length} system messages`
    );

    return [
        {
            role: "system",
            content,
        },
        ...otherMessages,
    ];
}

const server = http.createServer((req, res) => {
    // We only need to modify chat completions.
    if (
        req.method === "POST" &&
        req.url.startsWith("/v1/chat/completions")
    ) {
        let body = "";

        req.on("data", (chunk) => {
            body += chunk;
        });

        req.on("end", () => {
            try {
                const payload = JSON.parse(body);

                if (Array.isArray(payload.messages)) {
                    console.log(
                        `[proxy] ${payload.model} - ${payload.messages.length} messages`
                    );

                    console.log(
                        "[proxy] roles:",
                        payload.messages.map((m) => m.role).join(" → ")
                    );

                    payload.messages = mergeSystemMessages(payload.messages);

                    console.log(
                        "[proxy] forwarded roles:",
                        payload.messages.map((m) => m.role).join(" → ")
                    );
                }

                const modifiedBody = JSON.stringify(payload);

                const headers = {
                    ...req.headers,
                    host: `${OLLAMA_HOST}:${OLLAMA_PORT}`,
